// test/match/band-duplicates.test.js — the strategy draft's duplicate switch, both directions, on the server.
//
// Owner 2026-10-24 「多人可选同一个策略」: data/config.json bandDraft.duplicatesAllowed (generated by tools/build-data.mjs from
// docs/research/01-core-data.json criticAddendum.bandDraft) is TRUE, so out of the box two seats of a co-op match may take
// the same strategy. shared/bandDraft.js holds the one definition; server/match/gamedata.js publishes it as
// GameData.bandDraft.duplicatesAllowed, Match.bandTaken is the single gate, and MatchViews puts the server's verdict on the
// wire as m.public.draft.duplicatesAllowed so the client greys exactly what the server would refuse.
//
// This file is the red/green proof for the switch: EVERY case runs twice — once on the real data (switch on, the shipped
// rule) and once with config.bandDraft.duplicatesAllowed overridden to false (the old 「队友已选」 rule). The off half is
// the important one: switching the feature on must not move the existing behaviour by a single byte.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { ERR, PHASE } from '../../shared/constants.js';
import { makeMatch, DATA } from './harness.js';
import { BAND_DRAFT_DEFAULTS, bandDuplicatesAllowed } from '../../shared/bandDraft.js';
import { BAND_TURN_SECONDS } from '../../server/match/Match.js';

const TURN_MS = BAND_TURN_SECONDS * 1000;

/** The real data with the duplicate switch off — the pre-2026-10-24 rule. */
const dataOff = () => ({ ...DATA, config: { ...DATA.config, bandDraft: { ...DATA.config.bandDraft, duplicatesAllowed: false } } });
/** Two rows of the same draft, one per switch position. */
const BOTH = [
  { label: 'switch ON (the shipped data)', data: () => DATA, duplicates: true },
  { label: 'switch OFF (config override)', data: dataOff, duplicates: false },
];

function draftOf(o = {}) {
  const h = makeMatch({ mode: 'coop', humans: 3, seed: 5, ...o }).start();
  for (const ps of h.m.players.values()) if (!ps.isBot) h.m.handle(ps.playerId, { t: 'g.infoReady' });
  h.sched.advance(1);
  assert.equal(h.m.phase, PHASE.BAND_DRAFT);
  return h;
}

test('shared/bandDraft.js: the switch defaults to allowed, and a non-boolean never flips it', () => {
  assert.equal(BAND_DRAFT_DEFAULTS.duplicatesAllowed, true, 'the official rule is the default');
  assert.equal(bandDuplicatesAllowed(null), true);
  assert.equal(bandDuplicatesAllowed({}), true);
  assert.equal(bandDuplicatesAllowed({ bandDraft: {} }), true);
  assert.equal(bandDuplicatesAllowed({ bandDraft: { duplicatesAllowed: 'false' } }), true, 'only a real boolean counts');
  assert.equal(bandDuplicatesAllowed({ bandDraft: { duplicatesAllowed: 0 } }), true);
  assert.equal(bandDuplicatesAllowed({ bandDraft: { duplicatesAllowed: true } }), true);
  assert.equal(bandDuplicatesAllowed({ bandDraft: { duplicatesAllowed: false } }), false);
});

test('the data ships the switch ON and GameData reads it (and the published verdict agrees)', () => {
  assert.equal(DATA.config.bandDraft.duplicatesAllowed, true, 'data/config.json bandDraft.duplicatesAllowed (tools/build-data.mjs)');
  for (const row of BOTH) {
    const h = draftOf({ data: row.data() });
    const m = h.m;
    assert.equal(m.gd.bandDraft.duplicatesAllowed, row.duplicates, row.label);
    assert.equal(m.publicView().draft.duplicatesAllowed, row.duplicates, `${row.label}: m.public.draft.duplicatesAllowed`);
    assert.equal(typeof m.publicView().draft.duplicatesAllowed, 'boolean', `${row.label}: a boolean on the wire`);
    // the rest of the draft's tunables are untouched by the switch
    assert.equal(m.gd.bandDraft.timeoutBandId, DATA.config.bandDraft.timeoutBandId);
    assert.equal(m.gd.bandDraft.skipsPerPlayer, DATA.config.bandDraft.skipsPerPlayer);
    m.dispose();
  }
});

test('bandTaken is the one gate: always false when allowed, the old teammate check when not', () => {
  for (const row of BOTH) {
    const h = draftOf({ data: row.data() });
    const m = h.m;
    const [first, second] = m.draft.order;
    assert.deepEqual(m.handle(first, { t: 'g.band', bandId: 'band_sarkazb' }), { ok: true }, row.label);
    assert.equal(m.bandTaken('band_sarkazb', second), !row.duplicates, `${row.label}: a teammate's pick`);
    assert.equal(m.bandTaken('band_sarkazb', first), false, `${row.label}: your own pick is never 队友已选`);
    assert.equal(m.bandTaken('band_amiya', second), false, `${row.label}: nobody holds it`);
    m.dispose();
  }
});

test('two seats take the same strategy when allowed; the second is refused when not', () => {
  for (const row of BOTH) {
    const h = draftOf({ data: row.data() });
    const m = h.m;
    const [first, second] = m.draft.order;
    assert.deepEqual(m.handle(first, { t: 'g.band', bandId: 'band_sarkazb' }), { ok: true }, row.label);
    const res = m.handle(second, { t: 'g.band', bandId: 'band_sarkazb' });
    if (row.duplicates) {
      assert.deepEqual(res, { ok: true }, `${row.label}: 多人可选同一个策略`);
      assert.equal(m.draft.picks[second], 'band_sarkazb', `${row.label}: both seats hold it`);
      assert.equal(h.ps(second).lp, DATA.bands.band_sarkazb.totalHp, `${row.label}: LP = startLp(band)`);
      assert.equal(h.ps(first).lp, DATA.bands.band_sarkazb.totalHp, `${row.label}: unchanged for the first seat`);
      assert.equal(m.draftTurn(), m.draft.order[2], `${row.label}: the turn moved on`);
    } else {
      assert.equal(res.error, ERR.BAD_TARGET, `${row.label}: refused`);
      assert.equal(res.detail, '队友已选', `${row.label}: the developer detail is byte-identical to before`);
      assert.equal(m.draft.picks[second], undefined, `${row.label}: nothing recorded`);
      assert.equal(m.draftTurn(), second, `${row.label}: the refused pick keeps the turn`);
    }
    m.dispose();
  }
});

test('every human idle: allowed ⇒ all share the default; forbidden ⇒ distinct strategies', () => {
  for (const row of BOTH) {
    const h = draftOf({ humans: 4, seed: 9, data: row.data() });
    const m = h.m;
    m.handle('p_0', { t: 'g.infoReady' }); // already ready (draftOf) — harmless
    h.run(() => m.phase !== PHASE.BAND_DRAFT, { maxTime: 4 * TURN_MS + 1 });
    assert.equal(m.phase, PHASE.BATTLE_CHECK, row.label);
    const ids = [...m.players.values()].map((ps) => ps.bandId);
    for (const id of ids) assert.ok(DATA.bands[id], `${row.label}: ${id}`);
    for (const ps of m.players.values()) assert.equal(ps.lp, DATA.bands[ps.bandId].totalHp, `${row.label}: ${ps.playerId} LP`);
    if (row.duplicates) {
      assert.deepEqual(ids, Array(4).fill('band_bldsk'), `${row.label}: no free-band hunt — everyone takes 华法琳`);
    } else {
      assert.equal(new Set(ids).size, ids.length, `${row.label}: distinct ${ids}`);
      assert.ok(ids.includes('band_bldsk'), `${row.label}: the first idle seat still gets the official default`);
    }
    m.dispose();
  }
});

test('the step cap (finishBandDraft) fills leftovers the same way in both positions', () => {
  for (const row of BOTH) {
    const h = draftOf({ data: row.data() });
    const m = h.m;
    const [first] = m.draft.order;
    assert.deepEqual(m.handle(first, { t: 'g.band', bandId: 'band_bldsk' }), { ok: true }, row.label);
    m.finishBandDraft(true);
    assert.equal(m.phase, PHASE.BATTLE_CHECK, row.label);
    const ids = [...m.players.values()].map((ps) => ps.bandId);
    for (const id of ids) assert.ok(DATA.bands[id], `${row.label}: ${id}`);
    if (row.duplicates) assert.deepEqual(ids, Array(3).fill('band_bldsk'), `${row.label}: the default, repeated`);
    else assert.equal(new Set(ids).size, ids.length, `${row.label}: still distinct ${ids}`);
    m.dispose();
  }
});

test('a departing seat passes with the default when allowed, with a free strategy when not', () => {
  for (const row of BOTH) {
    const h = draftOf({ data: row.data() });
    const m = h.m;
    const [first, second] = m.draft.order;
    assert.deepEqual(m.handle(first, { t: 'g.band', bandId: 'band_bldsk' }), { ok: true }, row.label);
    m.onLeave(second);
    if (row.duplicates) assert.equal(m.draft.picks[second], 'band_bldsk', `${row.label}: the leaver may share 华法琳`);
    else assert.notEqual(m.draft.picks[second], 'band_bldsk', `${row.label}: the leaver does not duplicate it`);
    assert.ok(DATA.bands[m.draft.picks[second]], `${row.label}: a real strategy either way`);
    m.dispose();
  }
});

test('bots: the day-one re-draw loop reads the gate — collisions when allowed, never when not', () => {
  // The AI seats are the clearest black-box probe of 「bot 也允许重复」. scheduleBandBot's re-draw loop is the DAY-ONE code,
  // untouched: it asks Match.bandTaken, and that is the switch's single door. With the switch ON the gate always says
  // false, so each bot keeps its one weighted draw and teammates do collide on a fair share of seeds; with it OFF the
  // loop still runs and a collision is impossible. The ON half asserts the collisions actually happen at these seeds —
  // that is what goes red if the switch ever stops reaching the gate.
  const seeds = [1, 2, 3, 4, 5, 6, 7, 9, 11];
  const collisions = [];
  for (const seed of seeds) {
    const h = draftOf({ humans: 1, bots: 3, seed });
    const m = h.m;
    h.run(() => m.phase !== PHASE.BAND_DRAFT || m.draftTurn() === 'p_0', { maxTime: 20000 });
    if (m.phase === PHASE.BAND_DRAFT && !m.draft.picks.p_0) {
      // 华法琳 may already be an AI seat's: allowed ⇒ the player may take it too (that is the shared strategy)
      assert.deepEqual(m.handle('p_0', { t: 'g.band', bandId: 'band_bldsk' }), { ok: true }, `seed ${seed}`);
    }
    h.run(() => m.phase !== PHASE.BAND_DRAFT, { maxTime: 60000 });
    assert.equal(m.phase, PHASE.BATTLE_CHECK, `seed ${seed}`);
    const ids = [...m.players.values()].map((ps) => ps.bandId);
    for (const id of ids) assert.ok(DATA.bands[id], `seed ${seed}: ${id}`);
    for (const ps of m.players.values()) assert.equal(ps.lp, DATA.bands[ps.bandId].totalHp, `seed ${seed}: ${ps.playerId} LP`);
    if (new Set(ids).size !== ids.length) collisions.push([seed, ids]);
    m.dispose();
  }
  assert.ok(collisions.length > 0, `switch ON: an AI seat takes a strategy a teammate holds — ${JSON.stringify(collisions)}`);
  for (const seed of seeds) {
    const h = draftOf({ humans: 1, bots: 3, seed, data: dataOff() });
    const m = h.m;
    h.run(() => m.phase !== PHASE.BAND_DRAFT || m.draftTurn() === 'p_0', { maxTime: 20000 });
    if (m.phase === PHASE.BAND_DRAFT && !m.draft.picks.p_0) {
      // the AI seats may already hold 华法琳: under the old rule the player has to take a free one
      const taken = new Set(Object.values(m.draft.picks));
      const free = m.gd.bandIds().find((id) => !taken.has(id));
      assert.ok(free, `switch OFF, seed ${seed}: a free strategy is left for the human`);
      assert.deepEqual(m.handle('p_0', { t: 'g.band', bandId: free }), { ok: true }, `switch OFF, seed ${seed}: ${free}`);
    }
    h.run(() => m.phase !== PHASE.BAND_DRAFT, { maxTime: 60000 });
    const ids = [...m.players.values()].map((ps) => ps.bandId);
    assert.equal(new Set(ids).size, ids.length, `switch OFF, seed ${seed}: distinct ${ids}`);
    for (const id of ids) assert.ok(DATA.bands[id], `switch OFF, seed ${seed}: ${id}`);
    m.dispose();
  }
});

test('a timeout takes the highlight when allowed even if held; falls back to the default when not', () => {
  for (const row of BOTH) {
    const h = draftOf({ data: row.data() });
    const m = h.m;
    const [first, second] = m.draft.order;
    assert.deepEqual(m.handle(first, { t: 'g.band', bandId: 'band_lisa' }), { ok: true }, row.label);
    assert.deepEqual(m.handle(second, { t: 'g.bandFocus', bandId: 'band_lisa' }), { ok: true }, row.label);
    if (row.duplicates) assert.equal(m.timeoutBand(second), 'band_lisa', `${row.label}: held or not, the highlight stands`);
    else assert.equal(m.timeoutBand(second), 'band_bldsk', `${row.label}: 队友已选 ⇒ the default`);
    h.sched.advance(TURN_MS + 1);
    assert.equal(m.draft.picks[second], row.duplicates ? 'band_lisa' : 'band_bldsk', `${row.label}: what the timeout assigned`);
    assert.equal(h.ps(second).lp, DATA.bands[m.draft.picks[second]].totalHp, `${row.label}: LP follows it`);
    m.dispose();
  }
});

test('solo is untouched by the switch: a free pick, no timer, no skip', () => {
  for (const row of BOTH) {
    const h = makeMatch({ mode: 'solo', seed: 2, data: row.data() }).start();
    const m = h.m;
    m.handle('p_0', { t: 'g.infoReady' });
    h.sched.advance(1);
    assert.equal(m.phase, PHASE.BAND_DRAFT, row.label);
    assert.equal(m.bandTaken('band_orchid', 'p_0'), false, row.label);
    assert.deepEqual(m.handle('p_0', { t: 'g.band', bandId: 'band_orchid' }), { ok: true }, row.label);
    assert.equal(h.ps('p_0').lp, DATA.bands.band_orchid.totalHp, row.label);
    m.dispose();
  }
});
